/**
 * Generates the low-level layer (src/generated/) from schemas/tools.json. Never edit src/generated by hand.
 *
 * Usage: npm run codegen   (or npm run regen to re-dump the schemas first)
 *
 * - types.ts    : one input type per tool; for multi-action tools (`actions` parameter), one type per action
 *                 and an "exactly one action per item" union.
 * - data.ts     : wrappers for the Data API tools (usable with a plain token).
 * - designer.ts : wrappers for the tools that require the Webflow Designer to be open (excluded from V1, not exported
 *                 by index).
 * - manifest.ts : list of tools, family, actions.
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { compile, type JSONSchema } from "json-schema-to-typescript";

interface Tool {
  name: string;
  description?: string;
  inputSchema: JSONSchema & { properties?: Record<string, JSONSchema>; required?: string[] };
}
const { tools, server } = JSON.parse(readFileSync("schemas/tools.json", "utf8")) as {
  tools: Tool[];
  server: { name: string; version: string };
};

/**
 * The schemas reuse sub-schemas through `$ref`s relative to the tool's root
 * ("#/properties/actions/items/..."). They are resolved before splitting by action, otherwise the refs break.
 */
function deref(root: unknown): unknown {
  const resolve = (ptr: string): unknown =>
    ptr.replace(/^#\/?/, "").split("/").filter(Boolean)
      .reduce<any>((o, k) => o?.[k.replace(/~1/g, "/").replace(/~0/g, "~")], root);
  const walk = (node: unknown, depth: number): unknown => {
    if (depth > 50) throw new Error("$ref trop profond (cycle ?)");
    if (Array.isArray(node)) return node.map((n) => walk(n, depth + 1));
    if (node && typeof node === "object") {
      const o = node as Record<string, unknown>;
      if (typeof o.$ref === "string" && o.$ref.startsWith("#")) {
        const { $ref, ...rest } = o;
        return walk({ ...(resolve($ref) as object), ...rest }, depth + 1);
      }
      return Object.fromEntries(Object.entries(o).map(([k, v]) => [k, walk(v, depth + 1)]));
    }
    return node;
  };
  return walk(root, 0);
}
for (const t of tools) t.inputSchema = deref(t.inputSchema) as Tool["inputSchema"];

const pascal =(s: string) => s.replace(/(^|[_\-\s]+)([a-z0-9])/gi, (_, __, c: string) => c.toUpperCase());
const camel = (s: string) => pascal(s).replace(/^./, (c) => c.toLowerCase());

/** Tool that requires the Webflow Designer to be open with the MCP app connected. */
const isDesigner = (t: Tool) =>
  /^designer tool/i.test((t.description ?? "").trim()) || t.name === "get_designer_app_connection_info";

/**
 * Multi-action tool: `actions` is an array of objects in which each property (all optional) is an action.
 * The schema does not enforce "a single action per item"; the generated type does.
 */
function actionsOf(t: Tool): Record<string, JSONSchema> | null {
  const a = t.inputSchema.properties?.actions as JSONSchema | undefined;
  const items = a && (a.items as JSONSchema | undefined);
  if (!items || Array.isArray(items) || !items.properties) return null;
  // Items with required fields (e.g. element_builder): a list of builds, not a choice of actions.
  if (Array.isArray(items.required) && items.required.length > 0) return null;
  return items.properties as Record<string, JSONSchema>;
}

const opts = { bannerComment: "", additionalProperties: false, format: false, strictIndexSignatures: true } as const;
const strip = (s: JSONSchema): JSONSchema => {
  const { $schema, ...rest } = s as JSONSchema & { $schema?: string };
  return rest;
};

const typeChunks: string[] = [];
const dataFns: string[] = [];
const designerFns: string[] = [];
const manifest: Array<{ name: string; kind: "data" | "designer"; actions: string[] | null }> = [];

for (const t of tools) {
  const T = pascal(t.name);
  const actions = actionsOf(t);
  const kind = isDesigner(t) ? "designer" : "data";
  manifest.push({ name: t.name, kind, actions: actions ? Object.keys(actions) : null });
  const doc = `/** ${(t.description ?? "").replace(/\*\//g, "*\\/").replace(/\s+/g, " ").trim().slice(0, 300)} */`;
  const out = kind === "data" ? dataFns : designerFns;

  if (!actions) {
    typeChunks.push(await compile(strip(t.inputSchema), `${T}Input`, opts));
    out.push(`${doc}\nexport const ${camel(t.name)} = (input: T.${T}Input) => callTool(${JSON.stringify(t.name)}, input as unknown as Record<string, unknown>);`);
    continue;
  }

  // One interface per action, then the "exactly one key" union.
  const members: string[] = [];
  const helpers: string[] = [];
  for (const [action, schema] of Object.entries(actions)) {
    const A = `${T}${pascal(action)}`;
    const argsSchema = (schema.type === "object" || schema.properties) ? strip(schema) : strip(schema);
    typeChunks.push(await compile(argsSchema, `${A}Args`, opts));
    members.push(`{ ${action}: ${A}Args }`);
    helpers.push(
      `  /** ${(schema.description ?? action).replace(/\s+/g, " ").slice(0, 200)} */\n` +
        `  ${camel(action)}: (base: T.${T}Base, args: T.${A}Args) => callTool(${JSON.stringify(t.name)}, { ...base, actions: [{ ${action}: args }] }),`,
    );
  }
  typeChunks.push(`/** One item of \`actions\` for ${t.name}: exactly one action. */\nexport type ${T}Action = ${members.join(" | ")};`);
  const { actions: _a, ...baseProps } = t.inputSchema.properties ?? {};
  const baseSchema: JSONSchema = {
    type: "object",
    properties: baseProps,
    required: (t.inputSchema.required ?? []).filter((r) => r !== "actions"),
    additionalProperties: false,
  };
  typeChunks.push(await compile(baseSchema, `${T}Base`, opts));
  typeChunks.push(`export type ${T}Input = ${T}Base & { actions: ${T}Action[] };`);
  out.push(
    `${doc}\nexport const ${camel(t.name)} = {\n` +
      `  /** Raw call, several actions run in order. */\n` +
      `  call: (input: T.${T}Input) => callTool(${JSON.stringify(t.name)}, input as unknown as Record<string, unknown>),\n` +
      helpers.join("\n") +
      `\n};`,
  );
}

const header = (what: string) =>
  `// Generated by scripts/codegen.ts from schemas/tools.json (${server.name} ${server.version}). Do not edit.\n// ${what}\n`;
mkdirSync("src/generated", { recursive: true });
writeFileSync("src/generated/types.ts", header("Tool input types.") + "/* eslint-disable */\n" + typeChunks.join("\n"));
const fnHeader = `import { callTool } from "../lib/client.js";\nimport type * as T from "./types.js";\n\n`;
writeFileSync("src/generated/data.ts", header("Data API tools.") + fnHeader + dataFns.join("\n\n") + "\n");
writeFileSync(
  "src/generated/designer.ts",
  header("Designer tools: require the Webflow Designer to be open with the MCP app. Excluded from V1.") + fnHeader + designerFns.join("\n\n") + "\n",
);
writeFileSync(
  "src/generated/manifest.ts",
  header("Tool list.") +
    `export const serverVersion = ${JSON.stringify(server)} as const;\n` +
    `export const tools = ${JSON.stringify(manifest, null, 2)} as const;\n`,
);
const nData = manifest.filter((m) => m.kind === "data").length;
console.log(`codegen : ${manifest.length} outils (${nData} Data, ${manifest.length - nData} Designer), ${typeChunks.length} types.`);
